92. sealed class WebSearchTool
93. {
94.     private static readonly HttpClient s_http = new()
95.     {
96.         DefaultRequestHeaders =
97.         {
98.             { "User-Agent", "Mozilla/5.0 (compatible; ResearchAgent/1.0)" }
99.         }
100.     };
101. 
102.     [Description("Searches the web for the given query and returns a summary of the top results.")]
103.     public async Task<string> SearchWeb(
104.         [Description("The search query string.")] string query)
105.     {
106.         try
107.         {
108.             var encoded = WebUtility.UrlEncode(query);
109.             var url = $"https://html.duckduckgo.com/html/?q={encoded}";
110.             var html = await s_http.GetStringAsync(url);
111. 
112.             var results = ParseResults(html);
113.             if (results.Count == 0)
114.                 return $"No results found for '{query}'.";
115. 
116.             var sb = new StringBuilder();
117.             sb.AppendLine($"Search results for: {query}");
118.             sb.AppendLine(new string('-', 40));
119.             foreach (var (title, snippet, link) in results.Take(5))
120.             {
121.                 sb.AppendLine($"• {title}");
122.                 sb.AppendLine($"  {snippet}");
123.                 if (!string.IsNullOrEmpty(link))
124.                     sb.AppendLine($"  Source: {link}");
125.                 sb.AppendLine();
126.             }
127. 
128.             return sb.ToString();
129.         }
130.         catch (Exception ex)
131.         {
132.             return $"Search failed: {ex.Message}";
133.         }
134.     }
135. 
136.     private static List<(string Title, string Snippet, string Link)> ParseResults(string html)
137.     {
138.         var results = new List<(string, string, string)>();
139. 
140.         // Extract result blocks from DuckDuckGo HTML response.
141.         var resultPattern = new Regex(
142.             @"class=""result__a""[^>]*href=""(?<url>[^""]*)""\s*[^>]*>(?<title>.*?)</a>.*?class=""result__snippet""[^>]*>(?<snippet>.*?)</",
143.             RegexOptions.Singleline);
144. 
145.         foreach (Match m in resultPattern.Matches(html))
146.         {
147.             var title = StripHtml(m.Groups["title"].Value);
148.             var snippet = StripHtml(m.Groups["snippet"].Value);
149.             var rawUrl = m.Groups["url"].Value;
150. 
151.             // DuckDuckGo wraps URLs in a redirect; try to extract the actual URL.
152.             var linkMatch = Regex.Match(rawUrl, @"uddg=([^&]+)");
153.             var link = linkMatch.Success
154.                 ? WebUtility.UrlDecode(linkMatch.Groups[1].Value)
155.                 : rawUrl;
156. 
157.             if (!string.IsNullOrWhiteSpace(title))
158.                 results.Add((title.Trim(), snippet.Trim(), link.Trim()));
159.         }
160. 
161.         return results;
162.     }
163. 
164.     private static string StripHtml(string s) =>
165.         WebUtility.HtmlDecode(Regex.Replace(s, "<[^>]+>", ""));
166. }
