 using System.ComponentModel;
 using System.Net;
 using System.Text;
 using System.Text.Json;
 using System.Text.RegularExpressions;
 using Microsoft.Agents.AI;
 using Microsoft.Extensions.AI;

 // ---------------------------------------------------------------------------
 // Research Agent – searches the web and takes notes, then summarises findings.
 // ---------------------------------------------------------------------------

 var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
     ?? throw new InvalidOperationException(
         "Set the OPENAI_API_KEY environment variable before running.");

 var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

 IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
     .GetChatClient(model)
     .AsIChatClient();

 // Instantiate the tool providers so their state persists across calls.
 var searchTool = new WebSearchTool();
 var notesTool = new NotesTool();

 var tools = new AITool[]
 {
     AIFunctionFactory.Create(searchTool.SearchWeb),
     AIFunctionFactory.Create(notesTool.AddNote),
     AIFunctionFactory.Create(notesTool.GetNotes),
 };

 var agent = new ChatClientAgent(
     chatClient,
     instructions: """
         You are a research agent. When given a topic you MUST:
         1. Search the web for information (use multiple varied queries).
         2. Save every important finding as a note with add_note.
         3. After you have gathered enough information, call get_notes to
            review everything, then provide a well-structured summary with
            key facts and sources.
         Always search at least twice with different queries before summarising.
         """,
     name: "ResearchAgent",
     description: "Researches a topic using web search and note-taking.",
     tools: tools);

 Console.WriteLine("╔══════════════════════════════════════════╗");
 Console.WriteLine("║       Research Agent  (type 'quit')      ║");
 Console.WriteLine("╚══════════════════════════════════════════╝");
 Console.WriteLine();

 var session = await agent.CreateSessionAsync();

 while (true)
 {
     Console.ForegroundColor = ConsoleColor.Cyan;
     Console.Write("Topic> ");
     Console.ResetColor();

     var input = Console.ReadLine();
     if (string.IsNullOrWhiteSpace(input) || input.Equals("quit", StringComparison.OrdinalIgnoreCase))
         break;

     Console.ForegroundColor = ConsoleColor.DarkGray;
     Console.WriteLine("\n⏳ Researching…\n");
     Console.ResetColor();

     try
     {
         var response = await agent.RunAsync(input, session);

         Console.ForegroundColor = ConsoleColor.Green;
         Console.WriteLine(response.Text);
         Console.ResetColor();
     }
     catch (Exception ex)
     {
         Console.ForegroundColor = ConsoleColor.Red;
         Console.WriteLine($"Error: {ex.Message}");
         Console.ResetColor();
     }

     Console.WriteLine();
 }

 // ---------------------------------------------------------------------------
 // Web Search Tool – fetches results via DuckDuckGo HTML (no API key needed).
 // ---------------------------------------------------------------------------

 sealed class WebSearchTool
 {
     private static readonly HttpClient s_http = new()
     {
         DefaultRequestHeaders =
         {
             { "User-Agent", "Mozilla/5.0 (compatible; ResearchAgent/1.0)" }
         }
     };

     [Description("Searches the web for the given query and returns a summary of the top results.")]
     public async Task<string> SearchWeb(
         [Description("The search query string.")] string query)
     {
         try
         {
             var encoded = WebUtility.UrlEncode(query);
             var url = $"https://html.duckduckgo.com/html/?q={encoded}";
             var html = await s_http.GetStringAsync(url);

             var results = ParseResults(html);
             if (results.Count == 0)
                 return $"No results found for '{query}'.";

             var sb = new StringBuilder();
             sb.AppendLine($"Search results for: {query}");
             sb.AppendLine(new string('-', 40));
             foreach (var (title, snippet, link) in results.Take(5))
             {
                 sb.AppendLine($"• {title}");
                 sb.AppendLine($"  {snippet}");
                 if (!string.IsNullOrEmpty(link))
                     sb.AppendLine($"  Source: {link}");
                 sb.AppendLine();
             }

             return sb.ToString();
         }
         catch (Exception ex)
         {
             return $"Search failed: {ex.Message}";
         }
     }

     private static List<(string Title, string Snippet, string Link)> ParseResults(string html)
     {
         var results = new List<(string, string, string)>();

         // Extract result blocks from DuckDuckGo HTML response.
         var resultPattern = new Regex(
             @"class=""result__a""[^>]*href=""(?<url>[^""]*)""\s*[^>]*>(?<title>.*?)</a>.*?class=""result__snippet""[^>]*>(?<snippet>.*?)</",
             RegexOptions.Singleline);

         foreach (Match m in resultPattern.Matches(html))
         {
             var title = StripHtml(m.Groups["title"].Value);
             var snippet = StripHtml(m.Groups["snippet"].Value);
             var rawUrl = m.Groups["url"].Value;

             // DuckDuckGo wraps URLs in a redirect; try to extract the actual URL.
             var linkMatch = Regex.Match(rawUrl, @"uddg=([^&]+)");
             var link = linkMatch.Success
                 ? WebUtility.UrlDecode(linkMatch.Groups[1].Value)
                 : rawUrl;

             if (!string.IsNullOrWhiteSpace(title))
                 results.Add((title.Trim(), snippet.Trim(), link.Trim()));
         }

         return results;
     }

     private static string StripHtml(string s) =>
         WebUtility.HtmlDecode(Regex.Replace(s, "<[^>]+>", ""));
 }

 // ---------------------------------------------------------------------------
 // Notes Tool – lets the agent save and retrieve research notes.
 // ---------------------------------------------------------------------------

 sealed class NotesTool
 {
     private readonly List<string> _notes = [];

     [Description("Saves an important research finding as a note for later reference.")]
     public string AddNote(
         [Description("The note text to save.")] string note)
     {
         _notes.Add(note);
         return $"Note #{_notes.Count} saved.";
     }

     [Description("Retrieves all saved research notes collected so far.")]
     public string GetNotes()
     {
         if (_notes.Count == 0)
             return "No notes saved yet.";

         var sb = new StringBuilder();
         sb.AppendLine($"Saved notes ({_notes.Count}):");
         for (var i = 0; i < _notes.Count; i++)
             sb.AppendLine($"  [{i + 1}] {_notes[i]}");

         return sb.ToString();
     }
 }
